const seen = new Set();
const output = [];
for (const [index, item] of $input.all().entries()) {
  const link = String(item.json.link ?? '').trim();
  const title = String(item.json.title ?? '').trim();
  const contentSnippet = String(item.json.contentSnippet ?? item.json.content ?? '').trim();
  if (!/^https?:\/\//i.test(link) || !title || !contentSnippet || seen.has(link)) continue;
