 if(!kinds.includes(value.kind)||!states[value.kind].includes(value.status))return fail('Natureza e situação temporal incompatíveis.');
 const event_at=value.event_at??null,event_date=value.event_date??null,event_timezone=value.event_timezone??null;
 if(event_at!==null&&!validEditorialTimestamp(event_at))return fail('Horário do fato inválido ou sem fuso.');
 if(event_date!==null&&!validEditorialDate(event_date))return fail('Data do fato inválida.');
 if(event_timezone!==null){if(typeof event_timezone!=='string'||!event_timezone.trim())return fail('Fuso do fato inválido.');try{new Intl.DateTimeFormat('en',{timeZone:event_timezone}).format(new Date(reference.execution_date));}catch{return fail('Fuso do fato inválido.');}}
