 if(!Number.isFinite(now))return fail('Referência editorial inválida.');
 const dateInZone=value=>{const fields=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:event_timezone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date(value)).filter(p=>p.type!=='literal').map(p=>[p.type,p.value]));return fields.year+'-'+fields.month+'-'+fields.day;};
 const localDate=event_timezone?dateInZone(now):reference.editorial_date;
 if(event_at&&event_date&&(event_timezone?dateInZone(event_at):event_at.slice(0,10))!==event_date)return fail('Data e horário do fato são incompatíveis.');
