function validateEditorialResearch(items,getTopic,getPrepared,log,getDirect) {
 const output=[];
 const canonical=value=>{
  if(typeof value!=='string'||/[\s\\]/.test(value)||/%(?![0-9a-f]{2})/i.test(value))return null;
  const match=value.match(/^(https?):\/\/([a-z0-9](?:[a-z0-9.-]*[a-z0-9])?)(:\d{1,5})?(\/[^?#]*)?(\?[^#]*)?(?:#.*)?$/i);if(!match)return null;
  const scheme=match[1].toLowerCase(),host=match[2].toLowerCase();if(host.includes('..')||host.startsWith('trends.google.')||/(^|\.)google\.[^/]+$/.test(host))return null;
  let port=match[3]||'';if(port&&(+port.slice(1)<1||+port.slice(1)>65535))return null;if((scheme==='https'&&port===':443')||(scheme==='http'&&port===':80'))port='';
  let query=[];try{query=(match[5]||'').slice(1).split('&').filter(Boolean).filter(part=>{const key=decodeURIComponent(part.split('=')[0].replace(/\+/g,' '));return !/^utm_/i.test(key)&&!['fbclid','gclid'].includes(key)}).sort();}catch{return null;}
