  const sources=(Array.isArray(dossier.sources)?dossier.sources:[]).filter(s=>consulted.has(canonical(s.url))&&sourceDate(s.published_at)&&sourceDate(s.updated_at)).map(s=>({url:canonical(s.url),name:typeof s.name==='string'&&s.name.trim()?s.name.trim():canonical(s.url).split('/')[2],published_at:s.published_at??null,updated_at:s.updated_at??null}));
  const cited=new Set(sources.map(s=>s.url)),seen=new Set(),facts=[];
  for(const f of Array.isArray(dossier.facts)?dossier.facts:[]){
   if(typeof f.text!=='string'||!f.text.trim()||!cited.has(canonical(f.source_url))||/google trends|volume (?:aproximado )?de buscas|buscas em alta/i.test(f.text))continue;
   const document=documents.find(d=>canonical(d.url)===canonical(f.source_url));
   const clean=value=>String(value||'').replace(/\s+/g,' ').trim();
   const quote=clean(f.evidence_excerpt);
   if(!document||quote.length<30||quote.length>500||!clean(document.text).includes(quote))continue;
   const temporal=temporalMetadata(f,trusted);if(!temporal.ok)continue;
   const text=f.text.trim(),key=text.toLowerCase().replace(/\s+/g,' ');if(seen.has(key))continue;seen.add(key);
   facts.push({text,source_url:canonical(f.source_url),...temporal.value});
  }
