  const supporting=facts.find(f=>f.text===primary.text.trim()&&f.source_url===primaryUrl&&f.kind===checked.value.kind&&f.status===checked.value.status&&f.event_at===checked.value.event_at&&f.event_date===checked.value.event_date&&f.event_timezone===checked.value.event_timezone);
  if(!supporting){skip('Fato central não corresponde a fato com fonte consultada e metadados compatíveis.');continue;}
